INSERT INTO solidays_dev.artist (id, name, image, description, youtubeurl, concertday, user_id ) VALUES
(1, 'BigFlo & Oli', 'bigfloOli.png', 'À Solidays, Bigflo et Oli sont comme à la maison. Pourtant, on ne sait jamais à quoi s’attendre à leur passage : freestyles légendaires, bains de foule électrisants, collabs folles… Des shows à l’image de leur carrière : en pleine évolution (pokémon). 2026 va le confirmer, avec l’arrivée d’un nouvel album plus qu’attendu. Ce serait dommage de les louper.', 'https://youtu.be/krJ7k1gG_28', 'Samedi', 1),
(2, 'Gims', 'gims.png', 'Maintenant qu’on a goûté au charisme XXL du rappeur francophone le plus écouté au monde (seul le ciel-euh peut s’y mesurer), on ne peut plus s’en passer! Voix de ténor, maximum beats, bonbons de sons, et pluie de tubes, on sait déjà qu’il va tout plier. Il fallait bien ça pour lancer le festival.', 'https://youtu.be/KG6ft_YDp5k', 'Vendredi', 1),
(3, 'Ino Casablanca', 'inoCasablanca.png','Mais Ino Casa qui l’arrête ? Son air est nonchalant, mais son flow millimétré et ses prods ultra calibrées l’ont propulsé au sommet en quelques titres. Et quels titres ! Il y tresse des influences maghrébines, hispaniques ou caribéennes, et nous plonge dans ses textes comme dans l’extase d’une teuf improvisée. Vous allez (beaucoup) en entendre parler.', 'https://youtu.be/ruR2Nv1kfX4', 'Vendredi', 1),
(4, 'L2B', 'L2B.png', 'Le cercle n’arrête pas de s’élargir. Après avoir transformé Châtelet en marée humaine, L2B a sold-out un Zenith puis deux Accor Arena en à peine 5 minutes. Parce qu’à trois, c’est mieux, le gang est resté soudé depuis l’enfance pour construire sa légende, et réunit aujourd’hui près de 6 millions d’auditeurs mensuels. Faut dire qu’ils étaient Nés pour briller.', 'https://youtu.be/gjluSd-ojsA', 'Dimanche', 1),
(5, 'La Mano 1.9', 'laMano.png', 'La Mano 1.9 a pris la main. Passé dans le top 3 des rappeurs les plus écoutés de France, il a rempli un Zénith en quelques minutes et enchaîné les tubes comme Messi enchaîne les dribbles. « Businessman », « Sexy Woman » ou « Parisienne » (en feat avec GIMS), chacun de ses titres devient un hymne. Hâte de les chanter (hurler*) avec vous sur les pelouses de Solidays.', 'https://youtu.be/1Zs6Wa3LvTM', 'Vendredi', 1),
(6, 'Luiza', 'luiza.png', 'France-Brésil, mais dans ce (perfect) match, tout le monde est gagnant. Impossible d’occulter son Soleil bleu (« les pieds dans l’eau, et la tête en feu ») : la jeune chanteuse franco-brésilienne est arrivée pour briller. Entre dub, pop et reggae, Luiza fait ce qu’elle veut et chante aussi bien en français qu’en brésilien. Que legal !', 'https://youtu.be/nd8RD3tjNQE', 'Samedi', 1),
(7, 'Mosimann', 'mosiman.png', 'Certains magiciens dosent, Mosimann, lui, n’en finit plus d’exploser. Après le succès des #dreamtracks, il a monté les marches du festival de Cannes 2025, et philosophe chaque semaine en musique sur France Inter. Mais il faut plus de 3 minutes de chronique pour saisir tout son génie. Un set rocambolesque à Solidays devrait aider.', 'https://www.youtube.com/watch?v=k7BV4YmmNpI', 'Dimanche', 1),
(8, 'Nico Moreno', 'nicoMoreno.png', 'Rave on ! Avec Nico Moreno, tout va très vite : il commence sa carrière a 16 ans et devient rapidement un dj et producteur majeur de la scène techno indus, aussi déchaîné qu’il est capable de déchaîner son public. Sur scène, les BPM s’emballent, la musique galope, et une fois qu’on y a goûté, impossible de décrocher.', 'https://www.youtube.com/watch?v=_R5sXcbRE7s', 'Vendredi', 1),
(9, 'Orelsan', 'orelsan.png', '16 ans de carrière, plus de 300 000 billets écoulés en 24 heures, 4 albums multi-certifiés et le meilleur démarrage de l’année pour son 5ème opus : OrelSan ne se contente plus de battre des records, il redéfinit les règles du jeu. Avec son ironie lucide, son flow tranchant et son regard toujours juste sur l’époque, le Normand transforme chacune de ses apparitions en un joyeux exutoire collectif. De retour à Solidays, il poursuit la construction de sa Civilisation…
